const parts = api.library('terrain', { variant: 3, size: params.size, height: params.height, resolution: params.resolution, roughness: params.roughness });
function cl(t) { return Math.max(0, Math.min(1, t)); }
function sm(t) { t = cl(t); return t * t * (3 - 2 * t); }
const mat = { preset: 'stone', color: '#ffffff', roughness: 0.95, vertexColors: true };
for (const p of parts) {
  p.mesh.vertexColor(function (x, y, z) {
    const n = cl(0.5 + 0.5 * api.fbm2(x * 0.07, z * 0.07, 2));
    const s = cl(0.5 + 0.5 * api.noise2(y * 1.1, (x + z) * 0.03));
    const rock = api.mix('#d9d1bd', '#a9a290', cl(0.55 * s + 0.45 * n));
    const floorC = api.mix('#cdbf9a', '#7fb0a2', n);
    const scrub = api.mix('#b4b184', '#7a8a52', n);
    let c = api.mix(floorC, rock, sm((y - 1) / 5));
    c = api.mix(c, scrub, sm((y - 41) / 7));
    return c;
  });
  api.add(p.mesh, mat);
}
api.autoColliders('trimesh');
return api.build();
